import React from 'react';
import { useNavigate } from 'react-router-dom';
import './MainPage.css'; // Ensure this file includes your existing styles
import './SearchBar.css'; // Include the styles for the search bar

const MainPage = () => {
  const navigate = useNavigate();

  const navigateToProfile = () => {
    navigate('/profile'); // Navigate to the profile page
  };

  return (
    <div className="main-page">
      <div className="header">
        <img src="path_to_image1.jpg" alt="Logo" className="logo" />
      </div>
      <div className="search-section">
        <form className="InputContainer">
          <label htmlFor="search" className="labelforsearch">Search</label>
          <div className="relative">
            <div className="searchIcon">
              {/* Replace with your actual search icon SVG */}
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                <path d="M19 19l-4-4m0-7A7 7 0 1 1 1 8a7 7 0 0 1 14 0Z" />
              </svg>
            </div>
            <input
              type="text"
              id="search"
              className="input"
              placeholder="Search..."
              required
            />
            <div className="border"></div>
            <button type="button" className="micButton">
              <div className="micIcon">
                {/* Replace with your actual microphone icon SVG */}
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                  <path d="M10 14a4 4 0 1 1-8 0V10a4 4 0 1 1 8 0v4zm2-4a2 2 0 1 1-4 0V6a2 2 0 1 1 4 0v4z" />
                </svg>
              </div>
            </button>
          </div>
        </form>
        <button className="profile-button" onClick={navigateToProfile}>
          Profile
        </button>
      </div>
    </div>
  );
};

export default MainPage;
